def find_median_string(k, s, t):
    def count_not_greater_than(s, target):
        return sum(1 for i in range(k) if s[i] <= target[i])

    left, right = 'a' * k, 'z' * k
    while left < right:
        mid = chr((ord(left[0]) + ord(right[0])) // 2)
        count_mid = count_not_greater_than(mid * k, t)
        count_s = count_not_greater_than(s, mid * k)
        if count_mid - count_s == (len(t) - len(s)) // 2 + 1:
            return mid * k
        elif count_mid > count_s:
            right = mid
        else:
            left = mid

    return left

